package com.example.Kcsj.erp;

import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.web.multipart.MultipartFile;
import javax.servlet.http.HttpServletRequest;
import java.time.*;
import java.util.*;
import static com.example.Kcsj.erp.ErpStore.*;

/** College workflows reuse encrypted records and the transaction-scoped write lock. */
@RestController
@RequestMapping("/college-work")
public class CollegeWorkController implements AttachmentAccess {
    final ErpStore store; final AuthService auth; final OperationsService op;
    final OperationsCampusService campus;
    final Set<String> modules=new HashSet<>(Arrays.asList("tasks","party","care","hygiene","archive"));
    public CollegeWorkController(ErpStore s,AuthService a,OperationsService o,OperationsCampusService c){store=s;auth=a;op=o;campus=c;}
    Map<String,Object> ok(Object data){return map("code",0,"data",data);}
    String kind(String module){if(!modules.contains(module))throw new ApiException(404,"模块不存在");return "college_"+module;}
    boolean staff(Map<String,Object> u){return auth.hasRole(u,"counselor","mentor","leader","business","logistics");}
    void staffOnly(Map<String,Object> u){op.allow(staff(u));}
    boolean studentScope(Map<String,Object> u,String sid){Map<String,Object> st=op.student(sid);return auth.hasRole(u,"counselor")?auth.inScope(u,st):staff(u)&&!s(u,"college").isEmpty()&&s(u,"college").equals(s(st,"college"));}
    boolean personScope(Map<String,Object> u,Map<String,Object> person){if(auth.hasRole(u,"admin"))return true;if(s(u,"id").equals(s(person,"id")))return true;if(auth.hasRole(person,"student"))return studentScope(u,s(person,"id"));return staff(u)&&!s(u,"college").isEmpty()&&s(u,"college").equals(s(person,"college"));}
    boolean visible(String module,Map<String,Object> u,Map<String,Object> r){
        if(module.equals("tasks"))return auth.hasRole(u,"admin")||(s(r,"ownerId").equals(s(u,"id"))&&staff(u))||s(r,"assigneeId").equals(s(u,"id"))||(auth.hasRole(u,"leader")&&s(u,"college").equals(s(r,"college"))&&!s(u,"college").isEmpty());
        if(module.equals("care"))return auth.hasRole(u,"counselor","mentor")&&s(r,"ownerId").equals(s(u,"id"))&&studentScope(u,s(r,"studentId"));
        if(module.equals("party"))return staff(u)&&studentScope(u,s(r,"studentId"));
        if(module.equals("hygiene"))return roomVisible(u,s(r,"bedId"));
        if(module.equals("archive")){if(!staff(u)&&!auth.hasRole(u,"admin"))return false;try{return visible(s(r,"sourceModule"),u,store.get(kind(s(r,"sourceModule")),s(r,"sourceId")));}catch(ApiException e){return false;}}
        return false;
    }
    boolean roomVisible(Map<String,Object> u,String bedId){try{Map<String,Object> bed=store.get("erp_bed",bedId);if(auth.hasRole(u,"leader","logistics"))return !s(u,"college").isEmpty()&&s(u,"college").equals(s(bed,"college"));if(auth.hasRole(u,"counselor","mentor"))for(Map<String,Object> b:store.all("erp_bed"))if(s(b,"campus").equals(s(bed,"campus"))&&s(b,"building").equals(s(bed,"building"))&&s(b,"room").equals(s(bed,"room"))&&!s(b,"studentId").isEmpty()&&studentScope(u,s(b,"studentId")))return true;}catch(ApiException ignored){}return false;}
    @GetMapping("/people") public Map<String,Object> people(HttpServletRequest q){Map<String,Object> u=auth.require(q);List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> p:store.all("user"))if(auth.active(p)&&personScope(u,p))out.add(map("id",s(p,"id"),"name",s(p,"name"),"role",s(p,"role"),"className",s(p,"className"),"college",s(p,"college")));return ok(out);}
    @GetMapping("/{module}") public Map<String,Object> list(@PathVariable String module,HttpServletRequest q){Map<String,Object> u=auth.require(q);List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> r:store.all(kind(module)))if(visible(module,u,r))out.add(view(r));return ok(out);}
    Map<String,Object> view(Map<String,Object> r){Map<String,Object> v=new LinkedHashMap<>(r);v.put("overdue",!s(r,"dueAt").isEmpty()&&op.due(s(r,"dueAt"))&&!Arrays.asList("completed","cancelled","closed","submitted").contains(s(r,"status")));return v;}
    @PostMapping("/{module}") @Transactional public Map<String,Object> create(@PathVariable String module,@RequestBody Map<String,Object> body,HttpServletRequest q){Map<String,Object> u=auth.require(q);kind(module);String client=op.text(body,"clientId",true);op.check(client.matches("[A-Za-z0-9_-]{8,80}"),"操作编号无效");String key=auth.digest(s(u,"id")+":"+module+":"+client);for(Map<String,Object> old:store.all("college_operation"))if(s(old,"id").equals(key)){op.check(s(old,"permissionStamp").equals(auth.permissionStamp(u)),"权限已变化，请刷新后重新发起");op.check(s(old,"signature").equals(auth.digest(body.toString())),"同一操作编号不能用于不同内容");for(Map<String,Object> prior:op.rows(old,"result"))op.allow(visible(module,u,store.get(kind(module),s(prior,"id"))));return ok(old.get("result"));}
        List<Map<String,Object>> result=new ArrayList<>();
        if(module.equals("tasks")){op.allow(staff(u)||auth.hasRole(u,"admin"));List<String> ids=op.strings(body,"assigneeIds");op.check(!ids.isEmpty()&&ids.size()<=500,"请选择1至500名接收人");String due=op.date(body,"dueAt",true),start=op.date(body,"startsAt",false);if(start.isEmpty())start=now();op.check(Instant.parse(due).isAfter(Instant.parse(start)),"截止时间必须晚于开始时间");op.check(!op.due(due),"任务截止时间必须晚于当前时间");String batch=id();for(String uid:ids){Map<String,Object> p=store.get("user",uid);op.allow(auth.active(p)&&personScope(u,p));Map<String,Object> r=op.fresh(u);r.putAll(map("title",op.text(body,"title",true),"content",op.text(body,"content",true),"dueAt",due,"startsAt",start,"batchId",batch,"assigneeId",uid,"assigneeName",s(p,"name"),"className",s(p,"className"),"college",s(p,"college"),"needsReview",b(body,"needsReview"),"status","pending","progress",0));op.save(kind(module),r,u,"create","");result.add(r);}}
        else {staffOnly(u);Map<String,Object> r=op.fresh(u);r.put("title",op.text(body,"title",true));r.put("content",op.text(body,"content",false));
            if(module.equals("party")||module.equals("care")){String sid=op.text(body,"studentId",true);op.allow(studentScope(u,sid));r.putAll(map("studentId",sid,"studentName",s(op.student(sid),"name"),"college",s(op.student(sid),"college"),"dueAt",op.date(body,"dueAt",true),"status","open"));
                if(module.equals("party")){String track=op.text(body,"track",true);op.check(Arrays.asList("league","party").contains(track),"请选择入团或入党");for(Map<String,Object> old:store.all(kind(module)))op.check(!(s(old,"studentId").equals(sid)&&s(old,"track").equals(track)&&!s(old,"status").equals("closed")),"该学生已有未结发展记录");r.putAll(map("track",track,"stage",0,"basis",op.text(body,"basis",true)));}
                else {op.allow(auth.hasRole(u,"counselor","mentor"));String type=op.text(body,"type",true);op.check(Arrays.asList("talk","followup").contains(type),"关怀类型无效");r.putAll(map("type",type,"level",op.text(body,"level",false)));}}
            else if(module.equals("hygiene")){String bed=op.text(body,"bedId",true);op.allow(roomVisible(u,bed));long score=op.number(body,"score",0);op.check(score<=100,"卫生评分须为0至100");Map<String,Object> room=store.get("erp_bed",bed);r.putAll(map("bedId",bed,"room",s(room,"campus")+" / "+s(room,"building")+" / "+s(room,"room"),"score",score,"checkedAt",op.date(body,"checkedAt",true),"status",score<60?"rectifying":"completed"));}
            else {String sourceModule=op.text(body,"sourceModule",true);op.check(!sourceModule.equals("archive"),"不能重复归档档案");Map<String,Object> source=store.get(kind(sourceModule),op.text(body,"sourceId",true));op.allow(visible(sourceModule,u,source));op.check(Arrays.asList("completed","closed","cancelled").contains(s(source,"status")),"事项办结后才能归档");for(Map<String,Object> old:store.all(kind(module)))op.check(!(s(old,"sourceModule").equals(sourceModule)&&s(old,"sourceId").equals(s(source,"id"))),"该事项已归档");r.putAll(map("sourceModule",sourceModule,"sourceId",s(source,"id"),"snapshot",new LinkedHashMap<>(source),"status","archived","archivedAt",now()));}
            List<String> files=op.attachments(body,u);
            if(module.equals("archive")){Map<String,Object> source=store.get(kind(s(r,"sourceModule")),s(r,"sourceId"));for(String fid:op.strings(source,"attachmentIds"))if(!files.contains(fid))files.add(fid);}
            r.put("attachmentIds",files);op.save(kind(module),r,u,"create","");result.add(r);}
        if(module.equals("tasks"))for(Map<String,Object> task:result){task.put("requiresFiles",b(body,"requiresFiles"));store.save(kind(module),task);}
        store.save("college_operation",map("id",key,"signature",auth.digest(body.toString()),"permissionStamp",auth.permissionStamp(u),"result",result,"createdAt",now()));return ok(result);
    }
    @PostMapping("/{module}/{rid}/action") @Transactional public Map<String,Object> action(@PathVariable String module,@PathVariable String rid,@RequestBody Map<String,Object> body,HttpServletRequest q){Map<String,Object> u=auth.require(q),r=store.get(kind(module),rid);op.allow(visible(module,u,r));op.version(r,body);String action=op.text(body,"action",true),reason=op.text(body,"reason",true);op.check(!Arrays.asList("cancelled","closed","archived","completed").contains(s(r,"status")),"已结束记录不能修改");
        if(module.equals("tasks")){boolean own=s(r,"assigneeId").equals(s(u,"id")),manager=s(r,"ownerId").equals(s(u,"id"))||auth.hasRole(u,"admin");
            if(action.equals("submit")&&b(r,"requiresFiles"))op.check(!op.attachments(body,u).isEmpty(),"此任务必须上传文件后提交");
            if(action.equals("extend")){String newDue=op.date(body,"dueAt",true);op.check(Instant.parse(newDue).isAfter(Instant.parse(s(r,"dueAt"))),"补时后的截止时间须晚于原截止时间");r.put("previousDueAt",s(r,"dueAt"));}
            if(Arrays.asList("progress","submit").contains(action)){op.allow(own);op.check(!s(r,"status").equals("submitted"),"待验收任务不能重复提交");op.check(!Instant.parse(s(r,"startsAt")).isAfter(Instant.now()),"任务尚未开始");long progress=op.number(body,"progress",0);op.check(progress<=100,"进度须为0至100");r.put("progress",action.equals("submit")?100:progress);r.put("progressNote",reason);r.put("status",action.equals("submit")?(b(r,"needsReview")?"submitted":"completed"):"in_progress");if(action.equals("submit")){r.put("submittedAt",now());r.put("attachmentIds",op.attachments(body,u));if(!b(r,"needsReview"))r.put("completedAt",now());}}
            else {op.allow(manager);if(action.equals("approve")||action.equals("return")){op.check(s(r,"status").equals("submitted"),"没有待验收提交");r.put("status",action.equals("approve")?"completed":"returned");if(action.equals("approve"))r.put("completedAt",now());}else if(action.equals("extend")){String due=op.date(body,"dueAt",true);op.check(!op.due(due)&&Instant.parse(due).isAfter(Instant.parse(s(r,"startsAt"))),"延期时间必须有效");r.put("dueAt",due);}else if(action.equals("cancel"))r.put("status","cancelled");else throw new ApiException(400,"任务操作无效");}}
        else if(module.equals("party")){staffOnly(u);if(action.equals("advance")){long stage=op.number(r,"stage",0);op.check(stage<(s(r,"track").equals("league")?3:5),"已经到达最后阶段");op.check(b(body,"verified"),"须人工核验规定程序与材料");r.put("stage",stage+1);r.put("dueAt",nextFollowup(body));r.put("basis",op.text(body,"basis",true));}else if(action.equals("close"))r.put("status","closed");else throw new ApiException(400,"发展操作无效");}
        else if(module.equals("care")){if(action.equals("followup")){r.put("dueAt",nextFollowup(body));r.put("content",reason);}else if(action.equals("close"))r.put("status","closed");else throw new ApiException(400,"关怀操作无效");}
        else if(module.equals("hygiene")&&action.equals("rectify"))r.put("status","completed");else throw new ApiException(400,"记录不支持此操作");
        if(module.equals("tasks")&&action.equals("submit")){List<Map<String,Object>> submissions=op.rows(r,"submissions");submissions.add(map("at",now(),"note",reason,"attachmentIds",new ArrayList<>(op.strings(r,"attachmentIds"))));r.put("submissions",submissions);}
        if(Arrays.asList("completed","cancelled","closed","submitted").contains(s(r,"status")))for(Map<String,Object> message:store.all("message"))if(s(message,"collegeRecordId").equals(rid)){message.put("resolved",true);store.save("message",message);}
        op.save(kind(module),r,u,action,reason);return ok(view(r));
    }
    @PostMapping("/review") @Transactional public Map<String,Object> review(@RequestBody Map<String,Object> body,HttpServletRequest q){
        Map<String,Object> u=auth.require(q);store.lockWrites();List<Map<String,Object>> selections=op.rows(body,"records");
        op.check(!selections.isEmpty()&&selections.size()<=500,"请选择1至500项待审核任务");String action=op.text(body,"action",true),reason=op.text(body,"reason",false);op.check(!reason.isEmpty(),"请填写审核意见或退回批注");
        op.check(Arrays.asList("approve","return").contains(action),"审核操作无效");Set<String> unique=new HashSet<>();
        for(Map<String,Object> selection:selections){String rid=s(selection,"id");op.check(unique.add(rid),"审核任务不能重复");Map<String,Object> r=store.get("college_tasks",rid);op.allow(visible("tasks",u,r)&&(auth.hasRole(u,"admin")||s(r,"ownerId").equals(s(u,"id"))));op.version(r,selection);op.check(s(r,"status").equals("submitted"),"部分任务已不在待审核状态，请刷新");}
        List<Object> result=new ArrayList<>();for(Map<String,Object> selection:selections)result.add(action("tasks",s(selection,"id"),map("version",selection.get("version"),"action",action,"reason",reason),q).get("data"));return ok(result);
    }
    @GetMapping("/dorms") public Map<String,Object> dorms(HttpServletRequest q){Map<String,Object> u=auth.require(q);staffOnly(u);List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> r:store.all("erp_bed"))if((auth.hasRole(u,"leader","logistics")&&!s(u,"college").isEmpty()&&s(u,"college").equals(s(r,"college")))||roomVisible(u,s(r,"id"))||(auth.hasRole(u,"counselor","mentor")&&!s(u,"college").isEmpty()&&s(u,"college").equals(s(r,"college"))&&s(r,"status").equals("available"))){Map<String,Object> v=new LinkedHashMap<>(r);if(!s(r,"studentId").isEmpty()&&!studentScope(u,s(r,"studentId")))v.remove("studentId");out.add(v);}return ok(out);}
    @PostMapping("/beds") @Transactional public Map<String,Object> bed(@RequestBody Map<String,Object> b,HttpServletRequest q){Map<String,Object> u=auth.require(q);staffOnly(u);op.allow(auth.hasRole(u,"counselor","leader","logistics"));op.check(!s(u,"college").isEmpty(),"请先配置学院");Map<String,Object> logistics=new LinkedHashMap<>(u);logistics.put("role","logistics");Map<String,Object> row=op.fresh(u);campus.change("beds",logistics,row,b,"create");return ok(row);}
    @PostMapping("/allocation") @Transactional public Map<String,Object> allocate(@RequestBody Map<String,Object> b,HttpServletRequest q){Map<String,Object> u=auth.require(q);staffOnly(u);List<String> students=op.strings(b,"studentIds"),beds=op.strings(b,"bedIds");op.check(!students.isEmpty()&&students.size()<=500&&beds.size()>=students.size(),"床位不足或人数超限");List<Map<String,Object>> plan=new ArrayList<>();Set<String> used=new HashSet<>();for(String sid:students){op.allow(studentScope(u,sid)&&auth.active(op.student(sid)));for(Map<String,Object> old:store.all("erp_bed"))op.check(!(s(old,"studentId").equals(sid)&&s(old,"status").equals("occupied"))&&!(s(old,"reservedFor").equals(sid)&&s(old,"status").equals("reserved")),"学生已有入住或预留");for(Map<String,Object> old:store.all("erp_housing"))if(s(old,"studentId").equals(sid))op.check(Arrays.asList("completed","cancelled","rejected").contains(s(old,"status")),"学生存在未结住宿事项");Map<String,Object> target=null;for(String bid:beds){Map<String,Object> candidate=store.get("erp_bed",bid);op.allow(!s(u,"college").isEmpty()&&s(candidate,"college").equals(s(u,"college")));if(!used.contains(bid)&&s(candidate,"status").equals("available")&&s(candidate,"conditions").equals(s(b,"conditions"))){target=candidate;break;}}op.check(target!=null,"符合住宿条件的空床位不足");used.add(s(target,"id"));plan.add(map("studentId",sid,"studentName",s(op.student(sid),"name"),"bedId",s(target,"id"),"bedTitle",s(target,"title")));}
        if(!b(b,"confirm"))return ok(plan);op.check(b(b,"conditionsVerified"),"请确认性别、无障碍及住宿条件已人工核验");String until=op.date(b,"reservedUntil",true);op.check(!op.due(until),"预留期限无效");for(Map<String,Object> p:plan){Map<String,Object> h=op.fresh(u);h.putAll(map("title","批量入住安排","studentId",s(p,"studentId"),"college",s(u,"college"),"type","checkin","targetBedId",s(p,"bedId"),"status","approved"));op.save("erp_housing",h,u,"batch_reserve","批量分配，待实际交接");Map<String,Object> bed=store.get("erp_bed",s(p,"bedId"));bed.putAll(map("status","reserved","housingId",s(h,"id"),"reservedFor",s(p,"studentId"),"reservedUntil",until));op.save("erp_bed",bed,u,"reserve","批量分配");}return ok(plan);
    }
    @GetMapping("/housing") public Map<String,Object> housing(HttpServletRequest q){Map<String,Object> u=auth.require(q);staffOnly(u);List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> h:store.all("erp_housing"))if(studentScope(u,s(h,"studentId")))out.add(h);return ok(out);}
    @PostMapping("/housing") @Transactional public Map<String,Object> housingCreate(@RequestBody Map<String,Object> body,HttpServletRequest q){Map<String,Object> u=auth.require(q);staffOnly(u);op.allow(studentScope(u,op.text(body,"studentId",true)));Map<String,Object> actor=new LinkedHashMap<>(u);actor.put("role","logistics");Map<String,Object> row=op.fresh(u);campus.change("housing",actor,row,body,"create");return ok(row);}
    @PostMapping("/housing/{rid}") @Transactional public Map<String,Object> housingAction(@PathVariable String rid,@RequestBody Map<String,Object> body,HttpServletRequest q){Map<String,Object> u=auth.require(q),r=store.get("erp_housing",rid);staffOnly(u);op.allow(studentScope(u,s(r,"studentId")));op.version(r,body);Map<String,Object> actor=new LinkedHashMap<>(u);actor.put("role","logistics");campus.change("housing",actor,r,body,op.text(body,"action",true));return ok(r);}
    @PostMapping("/imports/{module}") @Transactional public Map<String,Object> importFile(@PathVariable String module,@RequestParam MultipartFile file,@RequestParam(defaultValue="false") boolean confirm,HttpServletRequest q)throws Exception{Map<String,Object> u=auth.require(q);staffOnly(u);op.allow(auth.hasRole(u,"counselor","leader","logistics"));op.check(module.equals("beds"),"当前批量导入支持床位；学生台账请使用现有预检导入");List<Map<String,Object>> rows=TabularImport.parse(file);op.check(rows.size()<=1000,"床位每批最多1000行");Set<String> keys=new HashSet<>();for(Map<String,Object> r:store.all("erp_bed"))keys.add(s(r,"campus")+"|"+s(r,"building")+"|"+s(r,"room")+"|"+s(r,"bed"));for(Map<String,Object> row:rows){String key=op.text(row,"campus",true)+"|"+op.text(row,"building",true)+"|"+op.text(row,"room",true)+"|"+op.text(row,"bed",true);op.check(keys.add(key),"床位重复："+key);op.text(row,"conditions",true);op.text(row,"source",true);}if(confirm){op.check(!s(u,"college").isEmpty(),"请先配置学院");Map<String,Object> actor=new LinkedHashMap<>(u);actor.put("role","logistics");for(Map<String,Object> row:rows)campus.change("beds",actor,op.fresh(u),row,"create");}return ok(map("count",rows.size(),"rows",rows,"committed",confirm));}
    @GetMapping("/preferences") public Map<String,Object> preferences(HttpServletRequest q){Map<String,Object> u=auth.require(q);for(Map<String,Object> r:store.all("college_preferences"))if(s(r,"id").equals(s(u,"id")))return ok(r);return ok(map("enabled",true,"interval",30,"leadHours",24));}
    @PostMapping("/preferences") @Transactional public Map<String,Object> preferences(@RequestBody Map<String,Object> b,HttpServletRequest q){Map<String,Object> u=auth.require(q);long interval=op.number(b,"interval",30),lead=op.number(b,"leadHours",24);op.check(interval>=10&&interval<=60&&lead>=1&&lead<=48,"间隔须为10至60分钟，临期阈值须为1至48小时");Map<String,Object> r=map("id",s(u,"id"),"enabled",b(b,"enabled"),"interval",interval,"leadHours",lead);store.save("college_preferences",r);return ok(r);}
    @GetMapping("/reminders") @Transactional public Map<String,Object> reminders(HttpServletRequest q){Map<String,Object> u=auth.require(q);store.lockWrites();Map<String,Object> prefs=(Map<String,Object>)preferences(q).get("data");List<Map<String,Object>> out=new ArrayList<>();int hour=ZonedDateTime.now(ZoneId.of("Asia/Shanghai")).getHour();if(!b(prefs,"enabled")||hour>=22||hour<8)return ok(out);for(String module:Arrays.asList("tasks","care","party"))for(Map<String,Object> r:store.all(kind(module)))if(remindable(module,u,r)&&!s(r,"dueAt").isEmpty()&&Instant.parse(s(r,"dueAt")).isBefore(Instant.now().plusSeconds(op.number(prefs,"leadHours",24)*3600))){String key=auth.digest(s(u,"id")+":"+s(r,"id"));Map<String,Object> stamp=null;for(Map<String,Object> old:store.all("college_popup"))if(s(old,"id").equals(key))stamp=old;if(stamp!=null&&Instant.parse(s(stamp,"at")).plusSeconds(op.number(prefs,"interval",30)*60).isAfter(Instant.now()))continue;out.add(map("id",s(r,"id"),"title",s(r,"title"),"module",module,"dueAt",s(r,"dueAt")));store.save("college_popup",map("id",key,"at",now()));}return ok(out);}
    String nextFollowup(Map<String,Object> body){String due=op.date(body,"dueAt",true);op.check(!op.due(due),"下次跟进时间必须晚于当前时间");return due;}
    boolean remindable(String module,Map<String,Object> u,Map<String,Object> r){return (!module.equals("tasks")||s(r,"startsAt").isEmpty()||!Instant.parse(s(r,"startsAt")).isAfter(Instant.now()))&&visible(module,u,r)&&!Arrays.asList("completed","cancelled","closed","submitted").contains(s(r,"status"))&&(module.equals("tasks")?s(r,"assigneeId").equals(s(u,"id")):s(r,"ownerId").equals(s(u,"id")));}
    @Scheduled(fixedDelay=60000) @Transactional public void automaticReminders(){
        store.lockWrites();Instant time=Instant.now();
        for(String module:Arrays.asList("tasks","care","party"))for(Map<String,Object> r:store.all(kind(module))){
            String uid=module.equals("tasks")?s(r,"assigneeId"):s(r,"ownerId");Map<String,Object> u;
            try{u=store.get("user",uid);}catch(ApiException e){continue;}
            long lead=24;for(Map<String,Object> p:store.all("college_preferences"))if(s(p,"id").equals(uid))lead=op.number(p,"leadHours",24);
            if(!auth.active(u)||!remindable(module,u,r)||s(r,"dueAt").isEmpty()||Instant.parse(s(r,"dueAt")).isAfter(time.plusSeconds(lead*3600)))continue;
            String phase=op.due(s(r,"dueAt"))?"overdue":"soon";
            if(s(r,"lastReminderPhase").equals(phase)&&s(r,"lastReminderDue").equals(s(r,"dueAt"))&&!s(r,"lastReminderAt").isEmpty()&&Instant.parse(s(r,"lastReminderAt")).plusSeconds(86400).isAfter(time))continue;
            String key=auth.digest(module+":"+s(r,"id")+":"+s(r,"dueAt")+":"+phase+":"+LocalDate.now(ZoneId.of("Asia/Shanghai")));
            boolean exists=false;for(Map<String,Object> m:store.all("message"))if(s(m,"id").equals(key))exists=true;
            if(!exists)store.save("message",map("id",key,"userId",uid,"title",(phase.equals("overdue")?"逾期提醒：":"临期提醒：")+s(r,"title"),"content","截止时间："+s(r,"dueAt"),"collegeModule",module,"collegeRecordId",s(r,"id"),"channel","in_app","createdAt",now(),"read",false,"automatic",true));
            r.putAll(map("lastReminderAt",time.toString(),"lastReminderPhase",phase,"lastReminderDue",s(r,"dueAt")));store.save(kind(module),r);
        }
    }
    @PostMapping("/share") @Transactional public Map<String,Object> share(@RequestBody Map<String,Object> body,HttpServletRequest q){Map<String,Object> u=auth.require(q);String module=op.text(body,"module",true);Map<String,Object> r=store.get(kind(module),op.text(body,"recordId",true));op.allow(visible(module,u,r));op.check(!module.equals("care"),"关怀记录不可通过普通分享发送");List<String> people=op.strings(body,"recipientIds");op.check(!people.isEmpty()&&people.size()<=50,"请选择1至50名接收人");for(String uid:people){Map<String,Object> p=store.get("user",uid);op.allow(auth.active(p)&&visible(module,p,r));store.save("message",map("id",id(),"userId",uid,"title","事项分享："+s(r,"title"),"collegeModule",module,"collegeRecordId",s(r,"id"),"channel","in_app","createdAt",now(),"read",false));}auth.audit(u,"college.share",module+":"+s(r,"id"));return ok(map("sent",people.size()));}
    @Override public boolean canRead(Map<String,Object> u,String fileId){for(String module:modules)for(Map<String,Object> r:store.all(kind(module)))if(op.strings(r,"attachmentIds").contains(fileId)&&visible(module,u,r))return true;return false;}
    @PostMapping("/export") @Transactional public Map<String,Object> export(@RequestBody Map<String,Object> body,HttpServletRequest q){
        Map<String,Object> u=auth.require(q);String module=op.text(body,"module",true);List<String> ids=op.strings(body,"recordIds");op.check(ids.size()<=5000,"每次最多导出5000条");
        List<Map<String,Object>> out=new ArrayList<>();
        if(module.equals("beds")||module.equals("housing")){
            List<Map<String,Object>> authorized=op.rows(module.equals("beds")?dorms(q):housing(q),"data");for(String rid:ids){Map<String,Object> found=null;for(Map<String,Object> record:authorized)if(s(record,"id").equals(rid))found=record;op.allow(found!=null);out.add(found);}
        }else for(String rid:ids){Map<String,Object> r=store.get(kind(module),rid);op.allow(visible(module,u,r));out.add(view(r));}
        auth.audit(u,"college.export",module+"，记录数 "+out.size());return ok(out);
    }
}
